namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);
        if (tier == CustomerTier.Blocked)
            return 0m;

        var adjusted = ApplyTierAdjustment(subtotal, tier);
        adjusted = ApplyDiscountOverride(adjusted, order.DiscountOverride);
        adjusted = ApplyHighValueDiscount(adjusted, subtotal);
        adjusted = ApplyChannelAdjustment(adjusted, order.Channel);

        return ClampToZero(adjusted);
    }

    private static decimal CalculateSubtotal(Order order)
    {
        decimal subtotal = 0m;
        foreach (var line in order.Lines)
            subtotal += line.UnitPrice * line.Quantity;

        return subtotal;
    }

    private static decimal ApplyTierAdjustment(decimal subtotal, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? subtotal * 0.95m : subtotal;

    private static decimal ApplyDiscountOverride(decimal adjusted, decimal? discountOverride)
    {
        var discount = discountOverride.GetValueOrDefault();
        return discount > 0m ? adjusted - discount : adjusted;
    }

    private static decimal ApplyHighValueDiscount(decimal adjusted, decimal subtotal) =>
        subtotal > 500m ? adjusted - 10m : adjusted;

    private static decimal ApplyChannelAdjustment(decimal adjusted, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Web => adjusted,
            OrderChannel.Phone => adjusted + 2m,
            OrderChannel.Marketplace => adjusted * 1.02m,
            _ => adjusted,
        };

    private static decimal ClampToZero(decimal adjusted) =>
        adjusted < 0m ? 0m : adjusted;
}
